/**
 * 合并审查 LLM 脚本
 *
 * 职责：检测 final-noun-index.json 中相邻且偏移连续的名词对，
 * 调用 LLM 判断是否应合并为复合名词（对应 ARCHITECTURE_v2.md 第5步）。
 *
 * 输入：
 *   final-noun-index.json（s0+s1 合并后的初步终词表）
 *
 * 输出：
 *   merge-review-report.json - 候选对 + LLM判断结果
 *   final-noun-index-merged.json - 应用合并后的最终终词表
 *
 * 用法：
 *   node merge-review-llm.js            # 完整运行（会调用LLM，产生费用）
 *   node merge-review-llm.js --dry-run  # 只统计候选对数量，不调用LLM
 */

import fs from 'fs';

const INPUT_PATH = 'C:\\Users\\Administrator\\Desktop\\decide-design-v2-main\\final-noun-index.json';
const DOCUVERSE_PATH = 'C:\\Users\\Administrator\\Desktop\\docuverse_cartographies_squizoanalythiques_Fe_lix_Guattari_1789114122714.docuverse.json';
const REPORT_PATH = 'C:\\Users\\Administrator\\Desktop\\decide-design-v2-main\\merge-review-report.json';
const OUTPUT_PATH = 'C:\\Users\\Administrator\\Desktop\\decide-design-v2-main\\final-noun-index-merged.json';

const ADJACENCY_TOLERANCE = 3; // 相邻容差（字符数），与 nounMerge.ts 保持一致
const CONTEXT_WINDOW = 50;
const MAX_CANDIDATES = process.env.MAX_CANDIDATES ? parseInt(process.env.MAX_CANDIDATES, 10) : Infinity;
const CONCURRENCY = parseInt(process.env.LLM_CONCURRENCY || '5', 10);
const BATCH_SIZE = parseInt(process.env.BATCH_SIZE || '10', 10);
const DRY_RUN = process.argv.includes('--dry-run');

// ---------- LLM 配置（复用项目 .env 约定） ----------
const BASE_URL = (process.env.LLM_BASE_URL || 'https://api.deepseek.com').replace(/\/$/, '');
const API_KEY = process.env.LLM_API_KEY || '';
const MODEL = process.env.LLM_MODEL || 'deepseek-chat';

async function callLLM(prompt, retryCount = 0) {
  const MAX_RETRIES = 3;
  const BASE_DELAY = 2000;
  try {
    const response = await fetch(`${BASE_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${API_KEY}`,
      },
      body: JSON.stringify({
        model: MODEL,
        temperature: 0.1,
        max_tokens: 4096,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (response.status === 429 && retryCount < MAX_RETRIES) {
      const delay = BASE_DELAY * Math.pow(2, retryCount);
      console.warn(`[429限流] 等待 ${delay}ms 后重试 (${retryCount + 1}/${MAX_RETRIES})...`);
      await new Promise((r) => setTimeout(r, delay));
      return callLLM(prompt, retryCount + 1);
    }
    if (!response.ok) {
      const text = await response.text();
      throw new Error(`LLM API 错误 ${response.status}: ${text.slice(0, 300)}`);
    }
    const data = await response.json();
    return data.choices?.[0]?.message?.content || '';
  } catch (err) {
    if (retryCount < MAX_RETRIES) {
      const delay = BASE_DELAY * Math.pow(2, retryCount);
      console.warn(`[网络错误] ${err.message}，等待 ${delay}ms 后重试...`);
      await new Promise((r) => setTimeout(r, delay));
      return callLLM(prompt, retryCount + 1);
    }
    throw err;
  }
}

/**
 * 合并审查 LLM：检查 final-noun-index.json 中相邻且偏移连续的名词
