  if (raw && !raw.startsWith('[FIG:') && raw.length >= 8) return raw;
  if (text) return text;
  const note = (chunk.faces?.fig?.note || '').trim();
  return note
    .replace(/请依据可见版面回答[^。]*。?/g, '')
    .replace(/勿编造未提供的文字[^。]*。?/g, '')
    .replace(/无文字层\/未OCR[^。]*。?/g, '')
    .trim();
