const nouns = idx.nouns;
const TOL = 3;

const startIndex = new Map();
for (const e of nouns) {
  for (const o of e.offsets) {
    if (!startIndex.has(o.start)) startIndex.set(o.start, []);
    startIndex.get(o.start).push(e);
  }
}

const pairCooc = new Map(); // leftId|rightId -> count (distinct occurrences)
for (const left of nouns) {
  for (const lo of left.offsets) {
    for (let gap = 0; gap <= TOL; gap++) {
      const rightStart = lo.end + gap;
      const rights = startIndex.get(rightStart) || [];
      for (const right of rights) {
        if (right.id === left.id) continue;
        const key = left.id + '|' + right.id;
        pairCooc.set(key, (pairCooc.get(key) || 0) + 1);
      }
    }
  }
}

const counts = [...pairCooc.values()];
const total = counts.length;
const eq1 = counts.filter(c => c === 1).length;
const eq2 = counts.filter(c => c === 2).length;
const ge2 = counts.filter(c => c >= 2).length;
const ge3 = counts.filter(c => c >= 3).length;
const ge5 = counts.filter(c => c >= 5).length;

console.log('unique pairs total:', total);
console.log('pairs occurring exactly once:', eq1, (eq1/total*100).toFixed(1)+'%');
console.log('pairs occurring exactly twice:', eq2);
console.log('pairs occurring >=2 times:', ge2, (ge2/total*100).toFixed(1)+'%');
console.log('pairs occurring >=3 times:', ge3);
console.log('pairs occurring >=5 times:', ge5);

console.log('\ntop 15 most recurring pairs:');
[...pairCooc.entries()].sort((a,b)=>b[1]-a[1]).slice(0,15).forEach(([k,c])=>console.log(c, k));
